async function createHearthB2BAppContexts(client, hearthApp, amount, status) {
    if (!client) throw new Error('No client')
    if (!hearthApp || !hearthApp.id) throw new Error('No app')

    const organizationAttrs = []
    for (let i = 0; i < amount; i++) {
        organizationAttrs.push({
            data: {
                dv: 1,
                sender: { dv: 1, fingerprint: faker.random.alphaNumeric(8) },
                tin: generateNiNumber(),
                country: 'en',
                // NOTE: padWithRandomChars ensures organization name is at least 10 characters long
                // This makes search tests more reliable when extracting substrings for testing
                name: padWithRandomChars(faker.company.name(), 10),
            }
        })
    }

    const organizations = await HearthOrganization.createMany(client, organizationAttrs)

    const attrs = []
    for (let i = 0; i < amount; i++) {
        attrs.push({
            data: {
                dv: 1,
                sender: { dv: 1, fingerprint: faker.random.alphaNumeric(8) },
                app: { connect: { id: hearthApp.id } },
                organization: { connect: { id: organizations[i].id } },
                status,
            }
        })
    }

    const objs = await HearthB2BAppContext.createMany(client, attrs)

    return [objs, attrs]
}

