async function importB2CAppByTestClient(client, app, hearthDevApp = null, hearthProdApp = null, extraAttrs = {}) {
    if (!client) throw new Error('no client')
    if (!app || !app.id) throw new Error('no app')
    if (hearthDevApp && !hearthDevApp.id) throw new Error('no hearthDevApp.id')
    if (hearthProdApp && !hearthProdApp.id) throw new Error('no hearthProdApp.id')

    const sender = { dv: 1, fingerprint: faker.random.alphaNumeric(8) }
    const from = {}
    if (hearthDevApp) {
        from.developmentApp =  { id: hearthDevApp.id }
    }
    if (hearthProdApp) {
        from.productionApp = { id: hearthProdApp.id }
    }

    const attrs = {
        dv: 1,
        sender,
        to: { app: { id: app.id } },
        from,
        options: { info: true, builds: true, publish: true, accessRight: true, conflictPolicy: 'delete' },
        ...extraAttrs,
    }
    const { data, errors } = await client.mutate(IMPORT_B2C_APP_MUTATION, { data: attrs })
    throwIfError(data, errors)
    return [data.result, attrs]
}

